	selectedRange = self.props.value

	if selectedRange != 'Custom':
		assetPath = self.view.custom.filter.assetPath
		paramsDict = {'assetPath': assetPath, 'selectedDateRange': selectedRange, 'clientTZ': self.session.props.device.timezone.id}
		system.perspective.print("setRange() called with %s" %(paramsDict))			
		startDate, endDate = system.kanoa.date.getDateRange(paramsDict)
