transforms.code:
countInfo = value['countInfo']
displayInfo = value['params']['display']

instances = []
for item in countInfo:
	rowColor = '--kcRed-60' if item['counterName'] == 'waste' else ''

	itemAsset = {"value": item['assetName'], "style": {"color": rowColor, 'textAlign': 'center'}}

	itemName = {"style": {"color": rowColor}}
	if item['workOrderName'] and displayInfo['showOrder']: itemName['value'] = "%s | %s"%(item['workOrderName'], item['itemName'] or '')
	else: itemName['value'] = "%s"%(item['itemName'] or '')

	if item['itemStatePath']:
		itemStateName = "%s %s"%(item['counterName'].title(), item['itemStateName'])
	else: itemStateName = item['counterName'].title()

	itemState = {"value": itemStateName, "style": {"color": rowColor}}

	units = item['itemUnitName'] or ''
	itemValue = "{:,.0f} {}".format(item['value'], units)

	itemValue = {"value": itemValue, "style": {"color": rowColor, 'textAlign': 'center'}}
	instances.append({"assetId": item['assetId'], "assetPath": item['assetPath'], "assetName": itemAsset, "itemName": itemName, "itemState": itemState, "itemValue": itemValue})

return instances


if len(value) == 0: return ''
count = system.math.sum([item['value'] for item in value if item['value'] is not None])
return str(int(count))

customMethods.script:
